li.OKResult:

me:AddMsg(XT("[NAME]解开红绳拆开新手礼包，箱中静静躺着以下宝物："));
me:DropAwardItem("Item_SkyStone", 64);
me:DropAwardItem("Item_BossZhuLong_TianLin", 1);
me:DropAwardItem("Item_MiBao_YinYangZhenTu", 1);
me:DropAwardItem("Item_BossZhuLong_LongYu", 1);
me:DropAwardItem("Item_BossZhuLong_Eye", 2);
me:DropAwardItem("Item_BossZhuLong_HeiLin", 5);
me:DropAwardItem("Item_BossZhuLong_BaiLin", 5);
me:DropAwardItem("Item_BossLong_Jing", 2);
me:DropAwardItem("Item_BossLong_Zhua", 2);
me:DropAwardItem("Item_ParasolWood", 64);
me:DropAwardItem("Item_StarEssence", 64);
me:DropAwardItem("Item_YaoLeather1", 180);
me:DropAwardItem("Item_Dan_FiveBaseFromLife", 1);
story:RemoveBindItem();


me:AddMsg(XT("[NAME]撬开锈死的锁扣，匣中封存的古修神念散逸而出，隐约指向几处上古修行者的踪迹……"));
local ok, err = pcall(function()
	local Evt = GameEventMgr or CS.XiaWorld.GameEventMgr.Instance;
	for i = 1, 3 do
		Evt:TriggerEvent(97);
	end
end);
if not ok then
	print("[JadeStartMod] 上古秘匣·古修触发失败: " .. tostring(err));
end
story:RemoveBindItem();


me:AddMsg(XT("[NAME]撬开锈死的锁扣，匣底三缕残息一触即散，各自投向远方……"));
local ok, err = pcall(function()
	local ids = { 53, 54, 55 };
	for i = 1, #ids do
		if me:HasSecret(ids[i]) == false then
			me:AddSecret(ids[i]);
		end
	end
end);
if ok then
	me:AddMsg(XT("不多时，江湖上便传出三处异样的消息：蛟龙、凶凤与那团阴阳之息，各有一处踪迹可循。"));
else
	print("[JadeStartMod] 上古秘匣·古兽触发失败: " .. tostring(err));
	me:AddMsg(XT("残息散尽，却没能指向任何去处。"));
end
story:RemoveBindItem();


me:AddMsg(XT("[NAME]解开红绳打开礼包，箱底一缕气运散作清风，飘向山门之外……"));
--参数说明：个数 / 品质等级（实际无效）(1-10) / 滞后时间(天) / 五维附加值 / 种族
me:AddJoiners(30, 9, 0, 9, 9, 9, 9, 9, "Human");
me:AddMsg(XT("不多时，山门外来了三十名凡人，说是流落至此，愿在山门求一处安身之所。"));
story:RemoveBindItem();


me:AddMsg(XT("[NAME]拆开礼包，一枚无名玉简落入掌心，玉简一触即碎，化作无数感悟涌入识海……"));
--第二个参数 true = 不走心情/悟性系数，原样加 80 亿
me:AddTreeExp(8000000000, true);
me:AddMsg(XT("良久，[NAME]睁开双眼，胸中已是豁然贯通。"));
story:RemoveBindItem();


me:AddMsg(XT("[NAME]拆开礼包，一缕清光绕身一周……"));
local ok, err = pcall(function()
	if me:IsTouchNeck() then
		-- 先破境，成功了再收走礼包
		me:NeckBroken();
		story:RemoveBindItem();
		me:AddMsg(XT("那缕清光直透眉心，周身气机轰然贯通——瓶颈应声而破，[NAME]睁眼时只觉云开月明，一身修为已再上层楼。"));
	else
		me:AddMsg(XT("清光却无处着力，随即散去：此刻并未卡在瓶颈上，礼包又自行封了回去。"));
	end
end);
if not ok then
	print("[JadeStartMod] 悟道礼包·冲击瓶颈失败: " .. tostring(err));
	me:AddMsg(XT("清光忽地一滞，终究没能冲开什么。礼包未损，可稍后再试。"));
end


me:AddMsg(XT("[NAME]解开礼包，里头是一叠发黄的卷宗，字迹杂乱，却处处指向同一段旧事……"));
local ok, err = pcall(function()
	local JH = CS.XiaWorld.JianghuMgr.Instance;
	for id = 1, 29 do
		JH:UnLockClue(id, false);
	end
	JH:UnLockClue(43, false);
end);
if ok then
	me:AddMsg(XT("卷宗阅罢，江湖秘闻中「神秘身影」「灭门之谜」「外传-上古信息」的线索尽数在握。"));
	me:AddMsg(XT("（外传说明）打开「江湖」界面的「秘闻」，进「外传：上古信息」，把「上古信息」这条线索选进「动机」栏，其余两栏随手挑几条已得的线索填上即可解开。"));
else
	print("[JadeStartMod] 线索解锁失败: " .. tostring(err));
	me:AddMsg(XT("可惜卷宗字迹含糊难辨，终究没能理出个头绪。"));
end
story:RemoveBindItem();


me:AddMsg(XT("[NAME]解开红绳，箱底一枚灵晶幽幽生辉，旁边压着三册残卷……"));
me:DropAwardItem("Item_Wonder_QianKunLingJing", 1);
me:DropEsoteric("Esoterica_MiBao_5");	-- 百毒真经残卷
me:DropEsoteric("Esoterica_MiBao_8");	-- 修罗血河宝录残卷
me:DropEsoteric("Esoterica_MiBao_9");	-- 星河遗录
me:AddMsg(XT("灵晶落在掌心，三册残卷上的字迹随之亮起——皆是秘宝的炼制之法。"));
story:RemoveBindItem();


me:AddMsg(XT("[NAME]解开红绳，箱底一卷幽光沉沉的书册浮起，封皮上几个古字微微发亮——《幽冥十方太乙救苦经》。"));
local ok, err = pcall(function()
	if world:IsGongUnLocked("God_Gong_3") == false then
		me:UnLockGong("God_Gong_3");
		story:RemoveBindItem();
		me:AddMsg(XT("书页无风自翻，一行行古字化作流光没入[NAME]眉心——幽冥十方，太乙救苦。。"));
	else
		me:AddMsg(XT("书册入手便自行散了：这门《幽冥十方太乙救苦经》早已得手。礼包未曾拆损，可另择一路。"));
	end
end);
if not ok then
	print("[JadeStartMod] 秘宝礼包·神修功法失败: " .. tostring(err));
	me:AddMsg(XT("书册忽然一沉，又落回箱底。礼包未损，可稍后再试。"));
end
